-- =====================================================================
-- 0102 · EMILY (TL-053-26, v2): A PROPOSTA NO MODELO JORNADA
--
-- Instrução dela, nov/26: carregar a Parte B do arquivo da TL-053-26 na v2,
-- com os ajustes que ela fez ao ver o sketch:
--   · liga modelo='jornada' (0101) e as telas: abertura, at a glance, quatro
--     narrativas, onde vai ficar (hotel + cada quarto), como se desloca,
--     dining, "Your proposal", fechamento;
--   · textos REVISADOS por instrução dela ("você não está escrevendo um
--     catálogo, está escrevendo uma experiência"): sem cronômetro e sem
--     lista; os fatos de cada experiência são os da Parte B, nada inventado;
--   · Vaticano reescrito, e o barco no Tibre vira experiência própria à
--     tarde (texto da TL-055);
--   · valores dela: quartos (4 noites, IVA incluso), carro Category 1/2,
--     experiências, opções dos dias 21, 28 e 2/7, transfers e assistência,
--     dining concierge 6 × € 70; support car sob consulta (sem valor);
--     transporte da caça às trufas como opcional (€ 790);
--   · General Conditions novas (pagamento 35% + saldo ou 35/30/35, Vaticano
--     à parte e 100% upfront após a confirmação, hotel com cancelamento
--     gratuito até 10 dias, termos digitais assinados na aprovação);
--   · fotos na pasta do hub (fotos/tl053/), com nomes neutros.
--
-- Mexe só na v2 (e0530000-0000-0000-0000-000000000002), criada nesta conversa, sem link enviado e sem
-- resposta. Guardado por responded_at nulo. As duas linhas que já existiam
-- (Castelfalfi e Bulgari) são ATUALIZADAS no lugar: mantêm o texto do hotel,
-- o "inclui", a estrutura, o site e os tours virtuais, e ganham os quartos em
-- bloco próprio. As outras entram novas. O estudo (v1) não é tocado.
--
-- Seção 7: ops_proposals (update na v2), ops_proposal_items (update de 2
-- linhas e insert na v2), ops_migrations. Sem delete. Nenhuma tabela do CRM.
-- =====================================================================

update ops_proposals set
    modelo = 'jornada', layout = 'apresentada', rate_mode = 'total',
    show_summary = true, show_conditions = true, confirm_mode = 'full', show_prices = true,
    cover_tag_en = 'Italy 2027', cover_title = 'Emily and Nathan', travel_window = 'June 20 to July 3, 2027',
    assurance_en = $q$Thirteen nights between southern Tuscany, the countryside around Castelfalfi, and Rome. The first days follow the pace of the Val di Chiana, the middle ones lean on the table and the land, and the trip closes in Rome, where you walk into the Vatican Museums with the keeper of the keys, before the public arrives.$q$,
    curations = $q$[{"cor": "verde", "opcao": "At a glance", "title_en": "At a glance", "dias_en": "You land in Florence on Sunday, June 20, and fly home from Rome on Saturday, July 3.\nTHE NIGHTS\n- Cortona, a historic palace · June 20 to 25 · 5 nights\n- Castelfalfi, Montaione · June 25 to 29 · 4 nights\n- Bulgari Hotel Roma, Piazza Augusto Imperatore · June 29 to July 3 · 4 nights\nFLIGHTS, AS BOOKED BY YOUR ADVISOR\nDelta reservation F8SCB6, business class.\n- Sat, Jun 19 · DL 9219, operated by KLM · Portland 1:05 pm to Amsterdam 7:40 am, Jun 20\n- Sun, Jun 20 · DL 9388, operated by KLM Cityhopper · Amsterdam 9:30 am to Florence 11:30 am\n- Sat, Jul 3 · DL 325 · Rome Fiumicino, Terminal 3, 12:20 pm to Seattle 3:30 pm\n- Sat, Jul 3 · DL 3913 · Seattle 5:40 pm to Portland 6:43 pm\nYou clear passport control in Amsterdam, so the landing in Florence works like a domestic arrival."}]$q$::jsonb,
    closing_en = $q$**A journey with Destinations by Dani**
Tuscan Lands Travel is the ground partner of Destinations by Dani in Italy. Our team coordinates the trip locally, from the stays to every transfer and experience, in direct contact with Danielle at every step.
Before the trip, our concierge can take care of your restaurant reservations, as described in Dining, and prepares a suggested route for the self-drive days with nothing scheduled, so those days have a direction whenever you want one.
During the trip, the concierge remains available through Danielle for what comes up along the way, a private car on a day you'd rather not drive, or a change of plan, always on request and subject to availability. Our team on the ground follows each day together with Danielle.$q$,
    conditions_en = $q$**This proposal**
This proposal does not hold or block any service and does not confirm availability. Availability and final rates are reconfirmed with each supplier at the time of booking, and rates may change at any time until then.

**After your approval**
Once you approve this proposal, our team reconfirms availability and rates with every supplier, to make sure the conditions are still valid. You then receive the digital terms and conditions, which you sign digitally and which form the contract for these services, together with a request for all the details needed for the bookings, and the payment link.

**Payment**
Payment is in euros, by credit card or bank transfer, and all prices include VAT. For every service except the Vatican experience, two options:
- Option 1: a 35% deposit on confirmation, and the balance by April 21, 2027, 60 days before travel.
- Option 2: a 35% deposit on confirmation, 30% by February 1, 2027, and the remaining 35% by April 21, 2027, 60 days before travel.
The Vatican experience with the Clavigero follows its own terms, below.
A credit card guarantee is requested for the rental car and for the hotel reservations. Our team will send you a secure link for this.

**Hotels**
Room rates include VAT. City tax and extras are not included and are paid directly at the hotel. Cancellation is free of charge up to 10 days before travel. Should the taxes or fees applied to accommodation change, the final room rate will change accordingly.

**Scheduled times and delays.** Each experience follows its scheduled timetable and ends at the agreed time. Delays caused by circumstances beyond Tuscan Lands Travel's control, such as flight delays, airport procedures or traffic, reduce the duration of the experience accordingly and do not extend its scheduled end time. No refund or compensation is due for the time lost.
**Additional time.** Services are provided for the duration stated in this proposal. Any time beyond the duration included, such as additional hours of a driver, guide or experience, is subject to availability and is charged to the client at the end of the service.
**Waiting time on transfers.** For private transfer services, a 20-minute grace period applies in case of traveler delay. Except in situations beyond the traveler's control, such as flight delays, the traveler acknowledges that any delay beyond this period will incur an additional charge of €105 per hour.

**Tickets are non-refundable.** Entrance tickets to monuments, museums and other sites, once issued, are non-refundable under any circumstances, regardless of the cancellation date.
**Nominal tickets.** Entry to major monuments strictly requires personalized tickets linked to official identity documents. The partner agency is responsible for providing exact guest names and dates of birth as they appear on their passports. Any mismatch, error, or late change may result in denied entry by monument authorities without possibility of refund or modification.
**Closure of monuments.** Monuments, museums and other sites may occasionally be closed due to force majeure or by decision of the sites' own management.

**Dining concierge**
The tables worth planning a day around are often booked months ahead. We choose restaurants for each day around your route, send you the shortlist, and book the ones you approve before you travel, subject to availability. €70 per night.

**Rental car, June 21 to 28**
Category 1: 1,400 km included; additional kilometers at €3 each. Category 2: 1,050 km included; additional kilometers at €4.50 each. A refundable security deposit is held on the driver's credit card, €3,000 for Category 1 and €4,000 for Category 2, equal to the maximum liability for damage and theft.

**Ferrari experience, June 29**
350 km included; additional kilometers at €22.50 each. The day before the drive, a security deposit of €4,500 is held on the client's credit card and released when the car is returned in good order; banks take between 3 and 30 days to complete the release. The client is responsible for any damage up to a deductible of €15,000; beyond that amount, insurance covers the rest.

**The Vatican with the keeper of the keys, July 1**
The Vatican Museums release the calendar for these early-morning visits only at the beginning of 2027. If you approve this experience, we request the date as soon as the calendar opens, and the experience is invoiced only once the Vatican confirms it. It is then paid in full, 100% upfront.

**Cancellation**
Cancellation of this booking follows the terms and conditions available at https://tuscanlandstravel.com/terms-conditions-tours/, except where specific conditions are set out above.

**Weather.** Tours operate rain or shine, except in cases of force majeure. Should severe weather prevent the execution of a tour and rescheduling is not possible, a full refund for the service will be issued to the agency.
**Professional insurance.** Tuscan Lands holds all required liability insurance under Italian law. This coverage does not replace individual travel insurance; guests must carry comprehensive personal travel insurance.
**Personal belongings.** Tuscan Lands and its suppliers are not responsible for lost, stolen, or damaged personal belongings during the execution of services.$q$,
    payment_options = $q$[{"key": "p1", "label_en": "Option 1 · 35% deposit, balance by April 21, 2027", "label": "Option 1 · 35% deposit, balance by April 21, 2027"}, {"key": "p2", "label_en": "Option 2 · 35% deposit, 30% by February 1, 2027, 35% by April 21, 2027", "label": "Option 2 · 35% deposit, 30% by February 1, 2027, 35% by April 21, 2027"}]$q$::jsonb,
    labels = coalesce(labels,'{}'::jsonb) || $q${"j_lead": {"en": "This proposal is built as one program, with every experience included. If you'd like to adjust any part of it, Danielle will arrange it with us."}}$q$::jsonb,
    sections = $q$[{"key": "cortona", "tipo": "narrativa", "modo": "dias", "title": "Cortona · June 20 to 25", "title_en": "Cortona · June 20 to 25", "intro_en": "For the Tuscan days, you're behind the wheel. On any day you'd rather not drive, our concierge can arrange a private car and driver, on demand and subject to availability."}, {"key": "castelfalfi", "tipo": "narrativa", "modo": "dias", "title": "Castelfalfi · June 25 to 29", "title_en": "Castelfalfi · June 25 to 29", "intro_en": "Four nights in the Tuscan countryside, with the car until the morning of June 28 and time left free for the resort."}, {"key": "aroma", "tipo": "narrativa", "modo": "dias", "title": "Castelfalfi to Rome · June 29", "title_en": "Castelfalfi to Rome · June 29"}, {"key": "roma", "tipo": "narrativa", "modo": "dias", "title": "Rome · June 29 to July 3", "title_en": "Rome · June 29 to July 3", "intro_en": "The days below are placed according to availability, once the logistics are confirmed. On the days with experiences, a private car takes you from the hotel."}, {"key": "stays", "tipo": "hospedagem", "modo": "blocos", "title": "Where you'll stay", "title_en": "Where you'll stay", "nights": 4, "intro_en": "One room in each hotel."}, {"key": "around", "tipo": "transporte", "modo": "blocos", "title": "Getting around", "title_en": "Getting around"}, {"key": "dining", "tipo": "dining", "modo": "blocos", "title": "Dining", "title_en": "Dining"}]$q$::jsonb,
    updated_at = now()
  where id = 'e0530000-0000-0000-0000-000000000002' and responded_at is null;
update ops_proposal_items set details_en = split_part(details_en, E'\n\n**', 1) || E'\n\nRoom images are by way of example; shades and arrangement of the furnishings may vary.', details = null,
    sort = 16, section = $q$stays$q$, service_date = $q$June 25 to 29, 2027$q$, kind = 'stay',
    photos = $q$["fotos/tl053/castelfalfi-borgo.jpg", "fotos/tl053/castelfalfi-piscina.jpg"]$q$::jsonb, units = $q$[{"key": "u1", "label": "Junior Suite Terrace", "label_en": "Junior Suite Terrace", "price": 9765, "optional": true, "desc_en": "The highlight is the private terrace, with panoramic views over rolling hills, olive groves and vineyards, an extension of the suite for a morning coffee or a sunset aperitif. Inside, refined furnishings in warm tones and materials that recall traditional Tuscan design. Marble bathroom with bathtub and shower.", "ficha_en": "40 m² / 431 sq ft · king bed · private terrace, countryside view", "photos": ["fotos/tl053/junior-suite-terrace-quarto.jpg", "fotos/tl053/junior-suite-terrace-terraco.jpg"]}, {"key": "u2", "label": "Suite Terrace", "label_en": "Suite Terrace", "price": 14160, "optional": true, "desc_en": "A sequence of spacious rooms: a living room, a walk-in closet, the bedroom and a travertine marble bathroom with separate shower and bathtub. Large windows light both the sleeping and the living area, and the large private terrace looks onto the Tuscan countryside. Turndown service, and access to the Beach Club in Forte dei Marmi.", "ficha_en": "61 m² / 657 sq ft · king bed · living room, walk-in closet, private terrace", "photos": ["fotos/tl053/suite-terrace-terraco.jpg", "fotos/tl053/suite-terrace-quarto.jpg"]}]$q$::jsonb, choice_group = $q$castelfalfi$q$, price = 0
  where proposal_id = 'e0530000-0000-0000-0000-000000000002' and 'Castelfalfi' in (coalesce(title,''),coalesce(title_en,''))
    and units::text not like '%"ficha_en"%' and exists (select 1 from ops_proposals where id = 'e0530000-0000-0000-0000-000000000002' and responded_at is null);
update ops_proposal_items set 
    sort = 17, section = $q$stays$q$, service_date = $q$June 29 to July 3, 2027$q$, kind = 'stay',
    photos = $q$["fotos/tl053/bulgari-terraco.jpg", "fotos/tl053/bulgari-spa.jpg"]$q$::jsonb, units = $q$[{"key": "u1", "label": "Premium Room", "label_en": "Premium Room", "price": 12400, "optional": true, "desc_en": "A walk-in closet and a chair with an ottoman give the room space to dress and sit away from the bed. The bathroom pairs coloured marble with a bathtub and a separate shower, and its palette carries into the fabrics and the Italian furnishings.", "ficha_en": "49 m² / 527 sq ft · king bed · city view", "photos": ["fotos/tl053/bulgari-premium.jpg"]}, {"key": "u2", "label": "Junior Suite", "label_en": "Junior Suite", "price": 15480, "optional": true, "desc_en": "A lounge with sofa and ottoman, a walk-in closet and butler service. Colour from the marble bathroom, with its large circular mosaic, carries into the fabrics and furniture, and the windows look over the piazza or Via della Frezza.", "ficha_en": "51 m² / 549 sq ft · king bed · city view", "photos": ["fotos/tl053/bulgari-junior-suite.jpg"]}]$q$::jsonb, choice_group = $q$bulgari$q$, price = 0
  where proposal_id = 'e0530000-0000-0000-0000-000000000002' and 'Bulgari Hotel Roma' in (coalesce(title,''),coalesce(title_en,''))
