insert into ops_proposal_items (proposal_id, sort, section, service_date, title, details_en, price, kind, photos, included_en, not_included_en, good_en, units, choice_group, extras, qty, unit_price, optional)
  select 'e0530000-0000-0000-0000-000000000002', 1, $q$cortona$q$, $q$June 21$q$, $q$Montalcino$q$, $q$The car is delivered to you in the morning, a few minutes from the palace, and the day goes to Montalcino, the hill town of Brunello.$q$, 0, $q$experience$q$, $q$["fotos/tl053/montalcino.jpg"]$q$::jsonb, null, null, null, $q$[{"key": "o1", "label": "Lunch with the chef at a historic estate", "label_en": "Lunch with the chef at a historic estate", "price": 755, "optional": true, "desc_en": "You walk through one of Montalcino's historic estates, then sit down to a lunch the chef builds around its wines, each course with its own glass.", "included_en": "the estate visit and the chef's lunch with wine pairings."}, {"key": "o2", "label": "Your own wine", "label_en": "Your own wine", "price": 685, "optional": true, "desc_en": "Alongside the winemaker, you blend a wine of your own, shaped around your taste, and take the bottle home with you.", "included_en": "the session with the winemaker, the tasting and your bottle.", "not_included_en": "lunch.", "good_en": "on request, we can look into shipping a case of your blend directly to your home."}]$q$::jsonb, $q$montalcino$q$, $q$[]$q$::jsonb, 1, null, false
  where exists (select 1 from ops_proposals where id = 'e0530000-0000-0000-0000-000000000002' and responded_at is null) and not exists (select 1 from ops_proposal_items x where x.proposal_id = 'e0530000-0000-0000-0000-000000000002' and x.sort = 1 and coalesce(x.title,'') = $q$Montalcino$q$);
