  select 'e0530000-0000-0000-0000-000000000002', 2, $q$cortona$q$, $q$June 22$q$, $q$Montepulciano and Pienza$q$, $q$Two hill towns about fifteen minutes apart, with the cypress lines and golden hills of the Val d'Orcia between them. The day is yours to wander their lanes and stop wherever the view opens up.$q$, 0, $q$experience$q$, $q$["fotos/tl053/pienza.jpg"]$q$::jsonb, null, $q$lunch.$q$, null, $q$[]$q$::jsonb, null, $q$[]$q$::jsonb, 1, null, false
  where exists (select 1 from ops_proposals where id = 'e0530000-0000-0000-0000-000000000002' and responded_at is null) and not exists (select 1 from ops_proposal_items x where x.proposal_id = 'e0530000-0000-0000-0000-000000000002' and x.sort = 2 and coalesce(x.title,'') = $q$Montepulciano and Pienza$q$);
