  select 'e0530000-0000-0000-0000-000000000002', 7, $q$castelfalfi$q$, $q$June 27$q$, $q$Siena and San Gimignano$q$, $q$Siena in the morning with a local guide, who shows you the corners of the city you would miss on your own. In the afternoon, San Gimignano and its towers, and a winery just outside the walls, where a glass of wine welcomes you. After a walk through the barrel room, you sit on the terrace facing the towers for four courses of Tuscan recipes in a modern key, each paired with the estate's wines, at lunch or dinner, as you prefer.$q$, 0, $q$experience$q$, $q$["fotos/tl053/siena.jpg", "fotos/tl053/san-gimignano.jpg"]$q$::jsonb, $q$your guide in Siena, the winery visit and the four-course meal with wine pairings.$q$, $q$other meals.$q$, null, $q$[{"key": "siena", "label": "Siena with a local guide", "label_en": "Siena with a local guide", "price": 430, "optional": false}, {"key": "vinicola", "label": "Winery visit and four-course meal, San Gimignano", "label_en": "Winery visit and four-course meal, San Gimignano", "price": 640, "optional": false}]$q$::jsonb, null, $q$[]$q$::jsonb, 1, null, false
