  select 'e0530000-0000-0000-0000-000000000002', 8, $q$castelfalfi$q$, $q$June 28$q$, $q$Castelfalfi$q$, $q$A slow morning at the resort, and the rental car is collected before noon.$q$, 0, $q$experience$q$, $q$["fotos/tl053/conversivel.jpg#p=50,72"]$q$::jsonb, null, null, null, $q$[{"key": "o1", "label": "A picnic at sunset", "label_en": "A picnic at sunset", "price": 595, "optional": true, "desc_en": "In the late afternoon a picnic is set for you on the Castelfalfi estate, with local products and wines, as the sun goes down over the hills.", "included_en": "the picnic with local products and wines."}, {"key": "o2", "label": "A vintage convertible, then the picnic", "label_en": "A vintage convertible, then the picnic", "price": 1685, "optional": true, "desc_en": "In the afternoon a restored vintage convertible is waiting at Castelfalfi. You take the wheel with the top down along the panoramic roads of the area, following a route prepared for you, to the spot chosen for the picnic, set with local products and wines as the sun goes down.", "included_en": "the vintage car for the afternoon, the suggested route, and the picnic with local products and wines.", "not_included_en": "the support car.", "good_en": "the car has a manual transmission. A support car can follow you along the way, on request."}]$q$::jsonb, $q$dia28$q$, $q$[{"key": "support", "unit": "o2", "label_pt": "Carro de apoio", "label_en": "Support car, following the vintage convertible", "price": null}]$q$::jsonb, 1, null, false
  where exists (select 1 from ops_proposals where id = 'e0530000-0000-0000-0000-000000000002' and responded_at is null) and not exists (select 1 from ops_proposal_items x where x.proposal_id = 'e0530000-0000-0000-0000-000000000002' and x.sort = 8 and coalesce(x.title,'') = $q$Castelfalfi$q$);
insert into ops_proposal_items (proposal_id, sort, section, service_date, title, details_en, price, kind, photos, included_en, not_included_en, good_en, units, choice_group, extras, qty, unit_price, optional)
  select 'e0530000-0000-0000-0000-000000000002', 9, $q$aroma$q$, $q$June 29$q$, $q$Behind the wheel of a Ferrari$q$, $q$A Ferrari 296 GTS is waiting for you at Castelfalfi. After a short briefing, some 350 km lie ahead: the Tuscan countryside, down to the Argentario coast for lunch by the sea, then on toward Rome and the Bulgari Hotel Roma. A lead car with qualified staff stays with you the whole way and carries your luggage, so all you think about is the road. Other models are available on request.$q$, 14900, $q$experience$q$, $q$["fotos/tl053/ferrari.jpg#p=62,72"]$q$::jsonb, $q$the Ferrari with 350 km, the lead car with qualified staff, fuel, parking, tolls and Telepass, luggage transport, and transfers to or from the hotel wherever the route can't start or end there directly.$q$, $q$lunch.$q$, $q$the car seats two, and the lead car carries up to three suitcases and three carry-on bags. The security deposit, damage deductible and additional kilometers are set out in the General Conditions.$q$, $q$[]$q$::jsonb, null, $q$[]$q$::jsonb, 1, null, false
  where exists (select 1 from ops_proposals where id = 'e0530000-0000-0000-0000-000000000002' and responded_at is null) and not exists (select 1 from ops_proposal_items x where x.proposal_id = 'e0530000-0000-0000-0000-000000000002' and x.sort = 9 and coalesce(x.title,'') = $q$Behind the wheel of a Ferrari$q$);
insert into ops_proposal_items (proposal_id, sort, section, service_date, title, details_en, price, kind, photos, included_en, not_included_en, good_en, units, choice_group, extras, qty, unit_price, optional)
  select 'e0530000-0000-0000-0000-000000000002', 10, $q$roma$q$, $q$June 30$q$, $q$The Colosseum$q$, $q$The day begins below the arena, in the underground of the Colosseum, where gladiators and animals waited before the games. It is visited in small groups at set times, and the first entry of the morning is the quietest. From there your guide takes you through the rest of the Colosseum and on to the Roman Forum, and the afternoon is yours in the center of Rome.
Each year the Colosseum opens on a few evenings. If one falls during your stay, we will propose it as an option.$q$, 885, $q$experience$q$, $q$["fotos/tl053/coliseu.jpg"]$q$::jsonb, $q$your guide, entry to the underground, the Colosseum and the Roman Forum, and pick-up at your hotel (one way).$q$, $q$lunch.$q$, null, $q$[]$q$::jsonb, null, $q$[]$q$::jsonb, 1, null, false
  where exists (select 1 from ops_proposals where id = 'e0530000-0000-0000-0000-000000000002' and responded_at is null) and not exists (select 1 from ops_proposal_items x where x.proposal_id = 'e0530000-0000-0000-0000-000000000002' and x.sort = 10 and coalesce(x.title,'') = $q$The Colosseum$q$);
insert into ops_proposal_items (proposal_id, sort, section, service_date, title, details_en, price, kind, photos, included_en, not_included_en, good_en, units, choice_group, extras, qty, unit_price, optional)
  select 'e0530000-0000-0000-0000-000000000002', 11, $q$roma$q$, $q$July 1$q$, $q$The Vatican with the keeper of the keys$q$, $q$At 6:00, while Rome is still waking up, you meet your private guide and the Clavigero, the keeper of the Vatican Museums' keys. He carries a ring of some 300 of them, the Sistine Chapel's among them, and this morning the museums open for the two of you.

You follow him from door to door: up the Simonetti staircase into the Pio Clementino, along the Galleries of the Candelabra, the Tapestries and the Maps as the lights come on, and on through the Raphael Rooms, with no one ahead of you and no one behind.

Then the Sistine Chapel is opened and lit, and for about twenty minutes it is yours, time enough to look up at Michelangelo's ceiling with no crowd around you.

The morning ends over breakfast at the bistro in the Cortile della Pigna, before the museums open to everyone else.$q$, 10045, $q$experience$q$, $q$["fotos/tl053/vaticano.jpg#p=50,30"]$q$::jsonb, $q$the private early-morning opening of the Vatican Museums with the Clavigero and your guide, and breakfast at the Cortile della Pigna.$q$, $q$lunch.$q$, null, $q$[]$q$::jsonb, null, $q$[]$q$::jsonb, 1, null, false
  where exists (select 1 from ops_proposals where id = 'e0530000-0000-0000-0000-000000000002' and responded_at is null) and not exists (select 1 from ops_proposal_items x where x.proposal_id = 'e0530000-0000-0000-0000-000000000002' and x.sort = 11 and coalesce(x.title,'') = $q$The Vatican with the keeper of the keys$q$);
insert into ops_proposal_items (proposal_id, sort, section, service_date, title, details_en, price, kind, photos, included_en, not_included_en, good_en, units, choice_group, extras, qty, unit_price, optional)
  select 'e0530000-0000-0000-0000-000000000002', 12, $q$roma$q$, $q$July 1$q$, $q$A private boat on the Tiber$q$, $q$The perfect setting for a toast to a meaningful journey together. A private aperitivo on board as you cruise the Tiber, with a privileged view of Rome's historic bridges: a joyful, intimate way to close the afternoon before dinner.$q$, 850, $q$experience$q$, $q$["fotos/tl053/barco-tibre.jpg"]$q$::jsonb, $q$a private luxury boat on the Tiber with a dedicated crew, an Italian aperitivo on board, and pick-up at your hotel.$q$, null, null, $q$[]$q$::jsonb, null, $q$[]$q$::jsonb, 1, null, false
  where exists (select 1 from ops_proposals where id = 'e0530000-0000-0000-0000-000000000002' and responded_at is null) and not exists (select 1 from ops_proposal_items x where x.proposal_id = 'e0530000-0000-0000-0000-000000000002' and x.sort = 12 and coalesce(x.title,'') = $q$A private boat on the Tiber$q$);
insert into ops_proposal_items (proposal_id, sort, section, service_date, title, details_en, price, kind, photos, included_en, not_included_en, good_en, units, choice_group, extras, qty, unit_price, optional)
  select 'e0530000-0000-0000-0000-000000000002', 13, $q$roma$q$, $q$July 2$q$, $q$Shopping in Rome$q$, null, 0, $q$experience$q$, $q$["fotos/tl053/shopping.jpg"]$q$::jsonb, null, null, null, $q$[{"key": "o1", "label": "Together, in a private lounge", "label_en": "Together, in a private lounge", "price": 1900, "optional": true, "desc_en": "A personal stylist welcomes you both in the luxury lounge of one of Rome's great department stores, four floors of Italian and international houses for men and women. Before you arrive she prepares a first selection for each of you, chosen around your tastes, so the time goes to trying on.", "included_en": "the stylist's preliminary selection, her time with you in the lounge, and a one-way transfer from your hotel.", "not_included_en": "purchases."}, {"key": "o2", "label": "A tour made for each of you", "label_en": "A tour made for each of you", "price": 2600, "optional": true, "desc_en": "One tour each, one in the morning and one in the afternoon, built around the boutiques each of you prefers. It begins before the trip, with a short questionnaire, two photographs and five outfits you usually wear: from these the stylist reads your silhouette, colors and proportions and sends a set of looks, and you choose your favorite eight. In Rome, three or four boutiques selected for you, with a short introduction to each house before you go in, and breakfast, brunch or an aperitivo depending on the time and the boutique.", "included_en": "for each of you (2 × € 1.300,00), the style analysis, the look selection, the tour with an English-speaking interpreter, and a one-way transfer from your hotel.", "not_included_en": "purchases, a private driver (available on request)."}]$q$::jsonb, $q$shopping$q$, $q$[]$q$::jsonb, 1, null, false
  where exists (select 1 from ops_proposals where id = 'e0530000-0000-0000-0000-000000000002' and responded_at is null) and not exists (select 1 from ops_proposal_items x where x.proposal_id = 'e0530000-0000-0000-0000-000000000002' and x.sort = 13 and coalesce(x.title,'') = $q$Shopping in Rome$q$);
