  select 'e0530000-0000-0000-0000-000000000002', 14, $q$roma$q$, $q$July 3$q$, $q$Departure$q$, $q$A private transfer to Fiumicino, Terminal 3, leaving the hotel around 9:00 for the 12:20 flight, with dedicated assistance at the airport from the entrance through to the gate.$q$, 0, $q$experience$q$, $q$["fotos/tl053/assistencia-aeroporto.jpg"]$q$::jsonb, null, null, null, $q$[]$q$::jsonb, null, $q$[]$q$::jsonb, 1, null, false
