  select 'e0530000-0000-0000-0000-000000000002', 19, $q$around$q$, $q$June 21 to 28$q$, $q$Your car in Tuscany$q$, $q$The car is delivered to you in Cortona on the morning of June 21, at the parking area a few minutes from the palace, and collected at Castelfalfi on the morning of June 28. Between those days, the route is yours. The exact model within each category is confirmed by availability.$q$, 0, $q$experience$q$, $q$[]$q$::jsonb, null, null, $q$a refundable security deposit is held on the driver's credit card, and kilometers beyond those included are charged separately. The terms are in the General Conditions.$q$, $q$[{"key": "c1", "label": "Category 1", "label_en": "Category 1", "price": 4845, "optional": true, "ficha_en": "Mercedes GLE, Maserati Grecale Modena or Audi Q8 · 1,400 km included"}, {"key": "c2", "label": "Category 2", "label_en": "Category 2", "price": 5850, "optional": true, "ficha_en": "Land Rover Defender 110, BMW X7 or Range Rover Sport · 1,050 km included"}]$q$::jsonb, $q$carro$q$, $q$[]$q$::jsonb, 1, null, false
